-- Migration 038: one Cleveland label ('Indians', the value the game's Cleveland category reads)
-- PURE ASCII. Needs owner approval (it unowns and deletes rows; everything is backed up and reversible).
--   Facts are stored under two labels for the same franchise; nothing reads 'Guardians' (categories.js maps the
--   "Cleveland Guardians" category to fact_value 'Indians'; no database function references 'Guardians').
--   UNOWNED (42): every owned 'Guardians' credit whose player has no 'Indians' credit (41). None is a playing stint:
--     MLB's records and Lahman show no Cleveland games (coaches and managers, e.g. Stephen Vogt, Eric Wedge, Carl Willis,
--     Mickey Callaway, Jimmy Dykes); Craig Albernaz, Joe Torres and Kai Correa never played in MLB. Plus Kai Correa's
--     'Mets' credit (no MLB games anywhere).
--   DELETED (1753): 'Guardians' rows duplicating an 'Indians' row (the same player owns 'Indians', or a same-name
--     'Indians' row exists). No information is lost: the 'Indians' row carries the same claim.
--   RELABELED (41): the remaining 'Guardians' rows (all unowned) become 'Indians'.
--   main_team 'Guardians' -> 'Indians' for 51 players (each owns an 'Indians' credit).
--   Owned 'Indians' credits are unchanged (2004), so no answer the game accepts today changes except the
--   42 unowned credits, which the game never read under 'Guardians' anyway (Correa/Mets is the one live change).
-- After it runs: node tests/check_prior.mjs against live. Left alone: the mirrored 'Guardians' rows in prior_tenure and
--   prior_times (derived tables; the prior functions read the category value 'Indians').
-- 0. GUARD first. 1. BACKUPS (RLS on, closed). 2. Changes with exact counts.

BEGIN;

DO $mig$
DECLARE n BIGINT;
BEGIN
  IF to_regclass('public.backup_20261016_facts_038') IS NOT NULL THEN RAISE EXCEPTION 'Migration 038 is already applied (found backup_20261016_facts_038). Nothing changed.'; END IF;
  SELECT count(*) INTO n FROM player_facts WHERE sport = 'MLB' AND fact_type = 'played_for_team' AND fact_value = 'Guardians';
  IF n <> 1794 THEN RAISE EXCEPTION '038 guard: expected 1794 Guardians rows, found %. Nothing changed.', n; END IF;
  SELECT count(*) INTO n FROM player_facts WHERE sport = 'MLB' AND fact_type = 'played_for_team' AND fact_value = 'Guardians' AND player_id IS NOT NULL;
  IF n <> 1750 THEN RAISE EXCEPTION '038 guard: expected 1750 owned Guardians rows, found %. Nothing changed.', n; END IF;
  SELECT count(*) INTO n FROM player_facts f JOIN (VALUES (1014562,8072),(1014646,2793),(1014955,9458),(1014961,39949),(1014988,62710),(1015084,6204),(1015125,23468),(1015194,7208),(1015226,2179),(1015233,45816),(1015250,43507),(1015308,68605),(1015513,5356),(1015757,5416),(1016448,26689),(1016461,8160),(1016466,5283),(1016547,5642),(1016607,2888),(1016693,40040),(1016707,72954),(1016720,41051),(1016788,12938),(1016911,68589),(1016962,12926),(1016965,6249),(1017032,12755),(1017165,33298),(1017268,13968),(1017302,12940),(1017392,12760),(1017504,7730),(1017596,4727),(1017730,19194),(1017786,34660),(1017794,7981),(1017917,28547),(1018035,7280),(1018059,53578),(1018187,27074),(1018320,13118),(1016912,68589)) AS x(id, pid) ON f.id = x.id AND f.player_id = x.pid;
  IF n <> 42 THEN RAISE EXCEPTION '038 guard: expected 42 rows to unown unchanged since review, found %. Nothing changed.', n; END IF;
  SELECT count(*) INTO n FROM players WHERE main_team = 'Guardians';
  IF n <> 51 THEN RAISE EXCEPTION '038 guard: expected 51 players with main_team Guardians, found %. Nothing changed.', n; END IF;
END $mig$;

