REVOKE ALL ON backup_20261016_players_038 FROM anon, authenticated;

DO $mig$
DECLARE n BIGINT;
BEGIN
  UPDATE player_facts f SET player_id = NULL, owner_method = 'unowned by 038: ' || b.reason_038 FROM backup_20261016_facts_038 b WHERE b.id = f.id AND b.reason_038 IS NOT NULL;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 42 THEN RAISE EXCEPTION '038: expected 42 rows unowned, got %', n; END IF;
  DELETE FROM player_facts f USING backup_20261016_facts_038 b WHERE b.id = f.id AND b.action_038 = 'delete';
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 1753 THEN RAISE EXCEPTION '038: expected 1753 rows deleted, got %', n; END IF;
  UPDATE player_facts f SET fact_value = 'Indians' FROM backup_20261016_facts_038 b WHERE b.id = f.id AND b.action_038 = 'relabel';
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 41 THEN RAISE EXCEPTION '038: expected 41 rows relabeled, got %', n; END IF;
  UPDATE players p SET main_team = 'Indians' FROM backup_20261016_players_038 b WHERE b.id = p.id;
  GET DIAGNOSTICS n = ROW_COUNT; IF n <> 51 THEN RAISE EXCEPTION '038: expected 51 main_team updates, got %', n; END IF;
END $mig$;

COMMIT;

-- --- CHECKS (run after COMMIT, alone, in a fresh session; one row) ---------------------------------
SELECT
  (SELECT count(*) FROM backup_20261016_facts_038)                                                                              AS backup_rows,
  (SELECT count(*) FROM backup_20261016_players_038)                                                                              AS backup_players,
  (SELECT count(*) FROM player_facts WHERE sport = 'MLB' AND fact_type = 'played_for_team' AND fact_value = 'Guardians') AS guardians_left,
  (SELECT count(*) FROM backup_20261016_facts_038 b WHERE NOT EXISTS (SELECT 1 FROM player_facts f WHERE f.id = b.id))          AS deleted_rows,
  (SELECT count(*) FROM player_facts f JOIN backup_20261016_facts_038 b ON b.id = f.id WHERE b.action_038 = 'relabel' AND f.fact_value = 'Indians') AS relabeled_rows,
  (SELECT count(*) FROM player_facts WHERE owner_method LIKE 'unowned by 038:%' AND player_id IS NULL)     AS unowned_rows_kept,
  (SELECT count(*) FROM player_facts WHERE sport = 'MLB' AND fact_type = 'played_for_team' AND fact_value = 'Indians' AND player_id IS NOT NULL) AS owned_indians,
  (SELECT count(*) FROM players WHERE main_team = 'Guardians')                                              AS main_team_guardians,
  (SELECT count(*) FROM player_facts f JOIN players p ON p.id = f.player_id WHERE p.wikipedia_page_id = 34028407 AND f.fact_value IN ('Indians', 'Guardians')) AS vogt_cleveland,
  (SELECT count(*) FROM player_facts f JOIN players p ON p.id = f.player_id WHERE p.wikipedia_page_id = 413386 AND f.fact_value = 'Indians' AND f.fact_type = 'played_for_team') AS boudreau_indians,
  (SELECT bool_and(relrowsecurity) FROM pg_class WHERE relname IN ('backup_20261016_facts_038', 'backup_20261016_players_038'))                        AS backup_rls,
  (SELECT count(*) FROM information_schema.role_table_grants WHERE table_name IN ('backup_20261016_facts_038', 'backup_20261016_players_038') AND grantee IN ('anon', 'authenticated')) AS backup_browser_grants;
